(()=>{const zh=document.documentElement.lang.startsWith('zh'),el=k=>document.getElementById('E03-'+k),defaults={probability:.1,cutoff:8};let p={...defaults};function distribution(){return Array.from({length:100},(_,i)=>{const l=i+1,c=l===100?(1-p.probability)**99:((99-l)*p.probability*p.probability+2*p.probability)*(1-p.probability)**(l-1);return {l,mass:l*c};});}function state(){const d=distribution();return {...p,massPercent:d.filter(v=>v.l>p.cutoff).reduce((s,v)=>s+v.mass,0),meanDP:100/(1+99*p.probability)};}function render(){for(const k of ['probability','cutoff']){el(k).value=p[k];el(k+'-value').textContent=p[k];}const d=distribution(),max=Math.max(...d.map(v=>v.mass),1),x=v=>80+640*Math.log10(v)/2,y=v=>330-270*v/max;let g='<rect width="800" height="420" fill="#faf9f5"/>';g+=`<rect x="80" y="60" width="${x(p.cutoff)-80}" height="270" fill="#cd803f" opacity=".12"/>`;for(const n of [1,2,5,10,20,50,100])g+=`<text x="${x(n)}" y="355" text-anchor="middle" font-size="15">${n}</text>`;for(let n=0;n<=4;n++){const v=max*n/4;g+=`<path d="M80 ${y(v)}H720" stroke="#dce4e7"/><text x="69" y="${y(v)+5}" text-anchor="end" font-size="15">${v.toFixed(1)}</text>`;}g+=`<path d="${d.map((v,i)=>`${i?'L':'M'}${x(v.l)} ${y(v.mass)}`).join('')}" fill="none" stroke="#186e83" stroke-width="3"/><text x="80" y="28" font-size="16">${zh?'橙色区：进入溶液的长度范围':'Orange region: lengths entering solution'}</text><text x="400" y="400" text-anchor="middle" font-size="17">${zh?'片段长度 / 重复单元数（对数轴）':'Fragment length / repeat units (log scale)'}</text><text x="20" y="210" transform="rotate(-90 20 210)" text-anchor="middle" font-size="16">${zh?'初始质量的百分比 / 每种长度':'Initial mass percentage / length class'}</text>`;el('plot').innerHTML=g;const s=state();el('readout').textContent=zh?`剩余聚合物质量 ${s.massPercent.toFixed(3)}%；全部片段的数均聚合度 ${s.meanDP.toFixed(3)}。阴影范围的片段移入溶液，全部重复单元仍守恒。`:`Retained polymer mass ${s.massPercent.toFixed(3)}%; number-average degree of all fragments ${s.meanDP.toFixed(3)}. Shaded fragment lengths enter solution; total repeat units remain conserved.`;}function set(n){if('probability'in n)p.probability=Math.min(.5,Math.max(0,+n.probability));if('cutoff'in n)p.cutoff=Math.round(Math.min(20,Math.max(1,+n.cutoff)));render();return state();}for(const k of ['probability','cutoff'])el(k).addEventListener('input',()=>set({[k]:+el(k).value}));el('more').addEventListener('click',()=>set({probability:p.probability+.05}));el('reset').addEventListener('click',()=>{p={...defaults};render();});window.CourseLab={set,state,reset(){p={...defaults};render();return state();}};render();})();
